 *      - -1 on failure.
 */
int fr_dns_global_init(void)
{
        if (instance_count > 0) {
                instance_count++;
                return 0;
        }

        if (fr_dict_autoload(dns_dict) < 0) return -1;
        if (fr_dict_attr_autoload(dns_dict_attr) < 0) {
                fr_dict_autofree(dns_dict);
                return -1;
        }

        instance_count++;

        return 0;
}

void fr_dns_global_free(void)
{
        if (--instance_count > 0) return;

        fr_dict_autofree(dns_dict);
}

